// Generated by AI (UnitTest MCP)
//! Optional local, OpenAI-compatible client for goal decomposition and semantic
//! conformance. Same posture as MindLeak's consolidation worker: off every hot
//! path, and it degrades cleanly (callers fall back) when no server is reachable.

use mindleak_model::{classify_ureq_error, failure, is_io_timeout, is_read_timeout};
pub use mindleak_model::{ModelCallProvenance, ModelCallSource, ModelHealth};
use serde_json::json;
use std::time::Duration;

use crate::error::{LodestarError, ModelFailureReason, Result};

const MIN_TIMEOUT_MS: u64 = 100;
const MAX_TIMEOUT_MS: u64 = 300_000;

#[derive(Debug, Clone, Copy)]
struct HttpPolicy {
    connect_timeout: Duration,
    read_timeout: Duration,
}

impl HttpPolicy {
    fn from_env() -> Self {
        HttpPolicy {
            connect_timeout: Duration::from_millis(env_bounded_u64(
                "MINDLEAK_HTTP_CONNECT_TIMEOUT_MS",
                1_000,
            )),
            read_timeout: Duration::from_millis(env_bounded_u64(
                "MINDLEAK_HTTP_TIMEOUT_MS",
                30_000,
            )),
        }
    }
}

fn env_bounded_u64(key: &str, default: u64) -> u64 {
    std::env::var(key)
        .ok()
        .and_then(|value| value.parse().ok())
        .unwrap_or(default)
        .clamp(MIN_TIMEOUT_MS, MAX_TIMEOUT_MS)
}

/// A candidate task produced by decomposition.
#[derive(Debug, Clone)]
pub struct TaskDraft {
    pub title: String,
    pub acceptance: String,
}

/// An OpenAI-compatible chat client pointed at a local server by default.
#[derive(Clone)]
pub struct LlmClient {
    pub base_url: String,
    pub model: String,
    pub api_key: String,
}

// Manual Debug so the bearer token never reaches a log, panic, or error chain.
impl std::fmt::Debug for LlmClient {
    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        f.debug_struct("LlmClient")
            .field("base_url", &self.base_url)
            .field("model", &self.model)
            .field(
                "api_key",
                &if self.api_key.is_empty() {
                    "<unset>"
                } else {
                    "<redacted>"
                },
            )
            .finish()
    }
}

impl Default for LlmClient {
    fn default() -> Self {
        LlmClient {
            base_url: std::env::var("LODESTAR_LLM_URL")
                .unwrap_or_else(|_| "http://localhost:11434/v1".to_string()),
            model: std::env::var("LODESTAR_MODEL").unwrap_or_else(|_| "glm4:9b".to_string()),
            api_key: std::env::var("LODESTAR_LLM_API_KEY").unwrap_or_default(),
        }
    }
}

impl LlmClient {
    /// A client pointed at an unroutable endpoint (`127.0.0.1:1`). Every request
    /// fails fast, forcing model-optional callers (`decompose`, `judge`) down
    /// their deterministic fallback. Use this to keep tests independent of any
    /// ambient local model instead of hand-rolling an unreachable URL per call
    /// site.
    pub fn unreachable() -> Self {
        LlmClient {
            base_url: "http://127.0.0.1:1/v1".to_string(),
            model: "unreachable".to_string(),
            api_key: String::new(),
        }
    }

    /// Probe the configured model only when a caller explicitly asks for it.
    pub fn model_health(&self) -> ModelHealth {
        if self.base_url.trim().is_empty() || self.model.trim().is_empty() {
            return ModelHealth::not_configured(&self.base_url, &self.model);
        }

        match self.chat_json(
            "Respond with ONLY JSON: {\"status\":\"ok\"}.",
            "Model health probe.",
        ) {
            Ok(_) => ModelHealth::healthy(&self.base_url, &self.model),
            Err(error) => match error.model_failure() {
                Some(failure) => ModelHealth::failed(&self.base_url, &self.model, failure),
                None => ModelHealth::failed(
                    &self.base_url,
                    &self.model,
                    &failure(ModelFailureReason::BadJson, false, error),
                ),
            },
        }
    }

    /// POST `/chat/completions` with a strict JSON response and parse the content.
    fn chat_json(&self, system: &str, user: &str) -> Result<serde_json::Value> {
        self.chat_json_with_policy(system, user, HttpPolicy::from_env())
    }

    fn chat_json_with_policy(
        &self,
        system: &str,
        user: &str,
        policy: HttpPolicy,
    ) -> Result<serde_json::Value> {
        let body = json!({
            "model": self.model,
            "stream": false,
            "response_format": { "type": "json_object" },
            "messages": [
                { "role": "system", "content": system },
                { "role": "user", "content": user }
            ]
        });
        let url = format!("{}/chat/completions", self.base_url.trim_end_matches('/'));
        let agent = ureq::builder()
            .timeout(policy.connect_timeout.saturating_add(policy.read_timeout))
            .timeout_connect(policy.connect_timeout)
            .timeout_read(policy.read_timeout)
            .build();
        let mut attempt = 0;
        let value: serde_json::Value = loop {
            attempt += 1;
            let mut req = agent.post(&url);
            if !self.api_key.is_empty() {
                req = req.set("Authorization", &format!("Bearer {}", self.api_key));
            }
            match req.send_json(&body) {
                Ok(response) => match response.into_json() {
                    Ok(value) => break value,
                    Err(error) if attempt == 1 && is_io_timeout(&error) => continue,
                    Err(error) => {
                        let reason = if is_io_timeout(&error) {
                            ModelFailureReason::Timeout
                        } else {
                            ModelFailureReason::BadJson
                        };
                        return Err(model_error(reason, true, error));
                    }
                },
                Err(error) if attempt == 1 && is_read_timeout(&error) => continue,
                Err(error) => return Err(classify_ureq_error(error).into()),
            }
        };
        let content = value
            .get("choices")
            .and_then(|c| c.get(0))
            .and_then(|c| c.get("message"))
            .and_then(|m| m.get("content"))
            .and_then(|c| c.as_str())
            .ok_or_else(|| {
                model_error(
                    ModelFailureReason::BadJson,
                    true,
                    "missing choices[0].message.content",
                )
            })?;
        serde_json::from_str(extract_json(content))
            .map_err(|error| model_error(ModelFailureReason::BadJson, true, error))
    }

    /// Phrase the question one agent should put to a peer whose live claim
    /// collides with theirs.
    ///
    /// Advisory drafting, never arbitration. The model is given two task
    /// descriptions and the shared scope and asked for one sentence; it is
    /// never asked who should win, because a model verdict carries no evidence
    /// and ADR-0009 makes evidence the basis of every verdict here. Callers
    /// fall back to `dialogue::template_question` when this fails, so the
    /// capability never depends on a reachable model.
    pub fn draft_question(
        &self,
        my_title: &str,
        their_title: &str,
        shared_scope: &str,
    ) -> Result<String> {
        let system = "You draft one short question from one engineer to another whose work \
             overlaps theirs. Ask only about intent and ordering - what they plan to do next, \
             and whose change should land first. Never decide who is right, never assign the \
             work, and never assert a fact you were not given. One or two sentences, plain \
             and specific. Respond with ONLY JSON: {\"question\":string}.";
        let user = format!(
            "My task: {my_title}\nTheir task: {their_title}\nWe both hold a live claim on: {shared_scope}"
        );
        let value = self.chat_json(system, &user)?;
        let question = value
            .get("question")
            .and_then(|q| q.as_str())
            .unwrap_or("")
            .trim()
            .to_string();
        if question.is_empty() {
            return Err(model_error(
                ModelFailureReason::BadJson,
                true,
                "model returned no question text",
            ));
        }
        Ok(question)
    }

    /// Break a goal into concrete, independently-claimable tasks.
    pub fn decompose(&self, goal_title: &str, goal_statement: &str) -> Result<Vec<TaskDraft>> {
        let system = "You are a planning engine. Break a goal into 2-6 concrete, \
             independently-claimable tasks. Respond with ONLY JSON: \
             {\"tasks\":[{\"title\":string,\"acceptance\":string}]}.";
        let user = format!("Goal: {goal_title}\n\n{goal_statement}");
        let value = self.chat_json(system, &user)?;
        let mut out = Vec::new();
        if let Some(arr) = value.get("tasks").and_then(|t| t.as_array()) {
            for t in arr {
                let title = t
                    .get("title")
                    .and_then(|x| x.as_str())
                    .unwrap_or("")
                    .trim()
                    .to_string();
                if title.is_empty() {
                    continue;
                }
                let acceptance = t
                    .get("acceptance")
                    .and_then(|x| x.as_str())
                    .unwrap_or("")
                    .trim()
                    .to_string();
                out.push(TaskDraft { title, acceptance });
            }
        }
        Ok(out)
    }

    /// Judge whether a change violates a constraint. Returns `(verdict, rationale)`
    /// where verdict is one of `aligned` / `violation` / `needs_human`.
    pub fn judge(&self, constraint: &str, change_summary: &str) -> Result<(String, String)> {
        let system = "You check whether a change violates a constraint. Respond with \
             ONLY JSON: {\"verdict\":\"aligned\"|\"violation\"|\"needs_human\",\
             \"rationale\":string}.";
        let user = format!("Constraint: {constraint}\n\nChange touches: {change_summary}");
        let value = self.chat_json(system, &user)?;
        parse_judgment(&value)
    }
}

fn model_error(
    reason: ModelFailureReason,
    reachable: bool,
    detail: impl ToString,
) -> LodestarError {
    failure(reason, reachable, detail).into()
}

fn parse_judgment(value: &serde_json::Value) -> Result<(String, String)> {
    let verdict = value
        .get("verdict")
        .and_then(|x| x.as_str())
        .ok_or_else(|| {
            model_error(
                ModelFailureReason::BadJson,
                true,
                "model returned no verdict",
            )
        })?;
    if !matches!(verdict, "aligned" | "violation" | "needs_human") {
        return Err(model_error(
            ModelFailureReason::BadJson,
            true,
            format!("model returned unsupported verdict: {verdict}"),
        ));
    }
    let rationale = value
        .get("rationale")
        .and_then(|x| x.as_str())
        .ok_or_else(|| {
            model_error(
                ModelFailureReason::BadJson,
                true,
                "model returned no rationale",
            )
        })?;
    let rationale = if verdict == "needs_human" && rationale.trim().is_empty() {
        "judge gave no reason"
    } else {
        rationale
    };
    Ok((verdict.to_string(), rationale.to_string()))
}

/// Extract the first JSON object from model content that may be wrapped in a
/// markdown code fence or surrounded by prose (glm4 and others do this even with
/// `response_format: json_object`). Braces are ASCII, so byte slicing is safe.
fn extract_json(content: &str) -> &str {
    match (content.find('{'), content.rfind('}')) {
        (Some(start), Some(end)) if end >= start => &content[start..=end],
        _ => content.trim(),
    }
}

#[cfg(test)]
mod tests {
    use super::*;
    use mindleak_model::test_support::{
        cold_then_warm_json_endpoint, json_endpoint, status_endpoint,
    };

    fn model_test_policy() -> HttpPolicy {
        HttpPolicy {
            connect_timeout: Duration::from_millis(100),
            read_timeout: Duration::from_millis(100),
        }
    }

    #[test]
    fn debug_redacts_the_api_key() {
        const SECRET: &str = "sk-lodestar-super-secret-token";
        let configured = LlmClient {
            base_url: "http://localhost:11434/v1".to_string(),
            model: "glm4:9b".to_string(),
            api_key: SECRET.to_string(),
        };
        let shown = format!("{configured:?}");
        assert!(
            !shown.contains(SECRET),
            "api key leaked into Debug: {shown}"
        );
        assert!(
            shown.contains("<redacted>"),
            "expected redaction marker: {shown}"
        );
        assert!(
            shown.contains("glm4:9b"),
            "model must still be shown: {shown}"
        );
        assert!(
            format!("{:?}", LlmClient::unreachable()).contains("<unset>"),
            "an empty key should render as <unset>"
        );
    }

    #[test]
    fn unreachable_client_is_pinned_away_from_ambient_configuration() {
        let client = LlmClient::unreachable();

        assert_eq!(client.base_url, "http://127.0.0.1:1/v1");
        assert_eq!(client.model, "unreachable");
        assert!(client.api_key.is_empty());
    }

    #[test]
    fn model_call_provenance_names_model_and_fallback_paths() {
        assert_eq!(
            ModelCallProvenance::model(),
            ModelCallProvenance {
                source: ModelCallSource::Model,
                fallback_reason: None,
            }
        );
        assert_eq!(
            ModelCallProvenance::fallback(ModelFailureReason::Timeout),
            ModelCallProvenance {
                source: ModelCallSource::Fallback,
                fallback_reason: Some(ModelFailureReason::Timeout),
            }
        );
    }

    #[test]
    fn model_health_distinguishes_not_configured_from_unreachable() {
        let not_configured = LlmClient {
            base_url: String::new(),
            model: String::new(),
            api_key: String::new(),
        }
        .model_health();
        assert!(!not_configured.configured);
        assert_eq!(not_configured.failure_reason, None);

        let unreachable = LlmClient::unreachable().model_health();
        assert!(unreachable.configured);
        assert!(!unreachable.reachable);
        assert!(!unreachable.responds_json);
        assert_eq!(
            unreachable.failure_reason,
            Some(ModelFailureReason::Unreachable)
        );
    }

    #[test]
    fn model_health_reports_a_reachable_non_json_endpoint() {
        let (base_url, server) = json_endpoint("/v1", b"not json");
        let health = LlmClient {
            base_url,
            model: "test".to_string(),
            api_key: String::new(),
        }
        .model_health();
        server.join().unwrap();

        assert!(health.configured);
        assert!(health.reachable);
        assert!(!health.responds_json);
        assert_eq!(health.failure_reason, Some(ModelFailureReason::BadJson));
    }

    #[test]
    fn cold_model_read_timeout_retries_once_and_uses_the_warm_response() {
        let (base_url, server) = cold_then_warm_json_endpoint(
            "/v1",
            br#"{"choices":[{"message":{"content":"{\"ok\":true}"}}]}"#,
            false,
        );
        let client = LlmClient {
            base_url,
            model: "test".to_string(),
            api_key: String::new(),
        };

        let result = client.chat_json_with_policy("system", "user", model_test_policy());
        let requests = server.join().unwrap();

        assert_eq!(result.unwrap(), json!({ "ok": true }));
        assert_eq!(requests, 2);
    }

    #[test]
    fn cold_model_body_timeout_retries_once_and_uses_the_warm_response() {
        let (base_url, server) = cold_then_warm_json_endpoint(
            "/v1",
            br#"{"choices":[{"message":{"content":"{\"ok\":true}"}}]}"#,
            true,
        );
        let client = LlmClient {
            base_url,
            model: "test".to_string(),
            api_key: String::new(),
        };

        let result = client.chat_json_with_policy("system", "user", model_test_policy());
        let requests = server.join().unwrap();

        assert_eq!(result.unwrap(), json!({ "ok": true }));
        assert_eq!(requests, 2);
    }

    // Regression: under a full parallel `cargo test` run, `model_test_policy`'s
    // 100ms read timeout (deliberately tight to simulate a cold model for the
    // retry tests above) can fire before this test's local loopback round trip
    // completes, so the client sees a genuine timeout instead of the 404 this
    // test exists to check, and the stub server's write then aborts. This test
    // asserts 4xx classification, not timeout behavior, so it gets its own
    // generous policy rather than sharing the one the retry tests need tight.
    #[test]
    fn model_policy_does_not_retry_a_4xx_rejection() {
        let (base_url, server) = status_endpoint("/v1", 404, "Not Found");
        let client = LlmClient {
            base_url,
            model: "missing".to_string(),
            api_key: String::new(),
        };
        let policy = HttpPolicy {
            connect_timeout: Duration::from_secs(2),
            read_timeout: Duration::from_secs(2),
        };

        let error = client
            .chat_json_with_policy("system", "user", policy)
            .unwrap_err();

        assert_eq!(
            error.model_failure().map(|failure| failure.reason),
            Some(ModelFailureReason::Misconfigured)
        );
        assert_eq!(server.join().unwrap(), 1);
    }

    #[test]
    fn extract_json_pulls_object_from_fence_or_prose() {
        assert_eq!(extract_json("```json\n{\"a\":1}\n```"), "{\"a\":1}");
        assert_eq!(extract_json("Sure:\n{\"a\":1} done"), "{\"a\":1}");
        assert_eq!(extract_json("{\"a\":1}"), "{\"a\":1}");
    }

    // The parser used to turn an unreadable answer into `needs_human`. That
    // made a protocol failure look like a real semantic verdict in the durable
    // receipt; a missing verdict must follow the unavailable-judge path.
    #[test]
    fn missing_verdict_is_not_a_semantic_verdict() {
        let error = parse_judgment(&json!({ "rationale": "unclear" }))
            .expect_err("missing verdict must be unavailable");

        let failure = error.model_failure().unwrap();
        assert_eq!(failure.reason, ModelFailureReason::BadJson);
        assert_eq!(failure.detail, "model returned no verdict");
    }

    // An unsupported value used to fall through to human review without naming
    // what the model actually returned, leaving the receipt unactionable.
    #[test]
    fn unsupported_verdict_names_the_value_that_came_back() {
        let error = parse_judgment(&json!({
            "verdict": "maybe",
            "rationale": "unclear"
        }))
        .expect_err("unsupported verdict must be unavailable");

        let failure = error.model_failure().unwrap();
        assert_eq!(failure.reason, ModelFailureReason::BadJson);
        assert_eq!(failure.detail, "model returned unsupported verdict: maybe");
    }

    // A deliberate request for human review is valid, but the old empty
    // rationale produced `semantic check needs human review: ` and gave the
    // human nothing to act on. The receipt must state that absence plainly.
    #[test]
    fn needs_human_without_rationale_says_the_judge_gave_no_reason() {
        let judgment = parse_judgment(&json!({
            "verdict": "needs_human",
            "rationale": "  "
        }))
        .expect("needs_human is a documented verdict");

        assert_eq!(
            judgment,
            (
                "needs_human".to_string(),
                "judge gave no reason".to_string()
            )
        );
    }

    #[test]
    fn missing_rationale_is_not_a_semantic_verdict() {
        let error = parse_judgment(&json!({ "verdict": "aligned" }))
            .expect_err("missing rationale must be unavailable");

        let failure = error.model_failure().unwrap();
        assert_eq!(failure.reason, ModelFailureReason::BadJson);
        assert_eq!(failure.detail, "model returned no rationale");
    }

    #[test]
    fn documented_judgments_keep_their_rationale() {
        for verdict in ["aligned", "violation", "needs_human"] {
            let judgment = parse_judgment(&json!({
                "verdict": verdict,
                "rationale": "because"
            }))
            .expect("documented verdict must parse");

            assert_eq!(judgment, (verdict.to_string(), "because".to_string()));
        }
    }

    /// Live round-trip against a running OpenAI-compatible server (Ollama +
    /// `glm4:9b` by default). Ignored in normal runs; exercise with
    /// `cargo test -p lodestar-core -- --ignored`. Proves decomposition and the
    /// semantic conformance judge against the JSON contract end to end.
    #[test]
    #[ignore = "requires a running local model (e.g. `ollama run glm4:9b`)"]
    fn live_decompose_and_judge_round_trip() {
        let client = LlmClient::default();

        let tasks = client
            .decompose(
                "Add FTS search",
                "Expose full-text search over node labels and content via an MCP tool.",
            )
            .expect("live decompose should parse tasks");
        assert!(!tasks.is_empty(), "model returned no tasks");
        eprintln!("live decompose -> {} tasks", tasks.len());

        let (verdict, rationale) = client
            .judge(
                "The write path must never call an LLM (zero-token ingestion).",
                "crates/mindleak-core/src/ingest/ast.rs",
            )
            .expect("live judge should return a verdict");
        assert!(
            matches!(verdict.as_str(), "aligned" | "violation" | "needs_human"),
            "unexpected verdict: {verdict} ({rationale})"
        );
        eprintln!("live judge -> {verdict}: {rationale}");
    }
}
